import React, { useEffect, useRef, useState } from "react"
import { LineChart } from "semiotic/line"
import {
  connectLiveChart,
  createLiveSource,
  LIVE_EVENTS,
  liveChartProps,
  type LiveSource,
  type Observation,
} from "./live-chart"
import "./live-chart.css"

/** The optional source lets lifecycle tests inspect subscriptions directly. */
export function LiveChartSession({ source }: { source: LiveSource }) {
  const chartRef = useRef<React.ComponentRef<typeof LineChart>>(null)
  const [connected, setConnected] = useState(true)
  const [playing, setPlaying] = useState(false)
  const [sourceCursor, setSourceCursor] = useState(source.cursor)
  const [display, setDisplay] = useState<{ rows: Observation[]; cursor: number }>({
    rows: [],
    cursor: 0,
  })

  useEffect(() => {
    if (!connected || !chartRef.current) return
    // Effects run after the child ref is available. Cleanup also handles
    // React StrictMode's setup/cleanup/setup cycle without duplicate listeners.
    return connectLiveChart(source, chartRef.current, (rows, cursor) => {
      setDisplay({ rows, cursor })
    })
  }, [source, connected])

  useEffect(() => {
    if (!playing || !connected) return
    const timer = window.setInterval(() => {
      const advanced = source.advance()
      setSourceCursor(source.cursor)
      if (!advanced || source.cursor === LIVE_EVENTS.length) setPlaying(false)
    }, 1_000)
    return () => window.clearInterval(timer)
  }, [source, playing, connected])

  function advance() {
    source.advance()
    setSourceCursor(source.cursor)
  }

  const finished = sourceCursor === LIVE_EVENTS.length
  const lag = sourceCursor - display.cursor
  return (
    <section className="task-live" aria-label="Live chart demonstration">
      <p>
        <strong>Synthetic fixture.</strong> Three readings start at 09:00–09:02. Five events include
        two corrections and three new observations. The line uses observation time; the event
        counter records processing order.
      </p>
      <div className="task-live__controls">
        <button type="button" onClick={advance} disabled={finished || playing}>
          Advance source
        </button>
        <button
          type="button"
          onClick={() => setPlaying((value) => !value)}
          disabled={!connected || finished}
        >
          {playing ? "Pause replay" : "Play replay"}
        </button>
        <button
          type="button"
          onClick={() => {
            setPlaying(false)
            setConnected((value) => !value)
          }}
        >
          {connected ? "Disconnect" : "Reconnect"}
        </button>
      </div>
      <p role="status" aria-live="polite" data-testid="live-chart-status">
        {connected ? "Connected" : "Disconnected"}. Source event {sourceCursor} of{" "}
        {LIVE_EVENTS.length}; display through event {display.cursor}.{" "}
        {lag ? `${lag} unapplied event${lag === 1 ? "" : "s"}.` : "Display is current."}
      </p>
      <p>
        {finished ? "Replay complete." : `Next event: ${LIVE_EVENTS[sourceCursor].label}.`}
        {!connected &&
          " Advance the source while disconnected, then reconnect to replace the frozen display with the source’s current window."}
      </p>
      <div data-testid="live-chart-rendering">
        {/* No data prop: push mode remains active across control re-renders. */}
        <LineChart ref={chartRef} {...liveChartProps} height={320} responsiveWidth />
      </div>
      <div className="task-live__table">
        <table>
          <caption>Records currently retained by the chart</caption>
          <thead>
            <tr>
              <th scope="col">Record ID</th>
              <th scope="col">Observation time</th>
              <th scope="col">Reading (units)</th>
            </tr>
          </thead>
          <tbody>
            {display.rows.map((row) => (
              <tr key={row.id}>
                <th scope="row">{row.id}</th>
                <td>09:{String(row.minute).padStart(2, "0")}</td>
                <td>{row.value}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p>
        Retention: the four latest observations by event time. Corrections replace a retained record
        by ID; older observations are removed. A reconnect takes the current source window, so it
        can recover a missed correction without retaining a complete event history. At completion,
        expect obs-03 = 17, obs-04 = 20, obs-05 = 16 and obs-06 = 19.
      </p>
    </section>
  )
}

export default function LiveChartExample() {
  const [source, setSource] = useState(createLiveSource)
  const [session, setSession] = useState(0)
  function restart() {
    setSource(createLiveSource())
    setSession((value) => value + 1)
  }
  return (
    <>
      <LiveChartSession key={session} source={source} />
      <button type="button" onClick={restart}>
        Restart fixture
      </button>
    </>
  )
}

import type { ComponentRef } from "react"
import type { LineChart } from "semiotic/line"

export interface Observation {
  id: string
  minute: number
  value: number
}

export const RETAINED_RECORDS = 4
export const INITIAL_OBSERVATIONS: Observation[] = [
  { id: "obs-01", minute: 0, value: 12 },
  { id: "obs-02", minute: 1, value: 18 },
  { id: "obs-03", minute: 2, value: 15 },
]

// Event order is processing order. A correction preserves the observation's
// event time and ID; it does not create a new point at its arrival time.
export const LIVE_EVENTS = [
  { row: { id: "obs-02", minute: 1, value: 14 }, label: "Correct obs-02 from 18 to 14" },
  { row: { id: "obs-04", minute: 3, value: 20 }, label: "Add obs-04 at minute 3" },
  { row: { id: "obs-05", minute: 4, value: 16 }, label: "Add obs-05; discard obs-01" },
  { row: { id: "obs-03", minute: 2, value: 17 }, label: "Correct obs-03 from 15 to 17" },
  { row: { id: "obs-06", minute: 5, value: 19 }, label: "Add obs-06; discard obs-02" },
] satisfies Array<{ row: Observation; label: string }>

export const liveChartProps = {
  xAccessor: "minute",
  yAccessor: "value",
  pointIdAccessor: "id",
  xLabel: "Observation time (minutes after 09:00)",
  yLabel: "Synthetic reading (units)",
  title: "The latest four observations",
  description:
    "Synthetic observations by event time. Corrections keep their original time and record ID.",
  summary:
    "Advance the source to inspect corrections and retention. Disconnect to freeze the displayed window, then reconnect to catch up.",
  showPoints: true,
  showGrid: true,
  accessibleTable: true,
  xExtent: [0, 5] as [number, number],
  yExtent: [0, 24] as [number, number],
}

type FeedMessage =
  | { kind: "snapshot"; rows: Observation[]; cursor: number }
  | { kind: "change"; row: Observation; removed: string[]; cursor: number }

/** A deterministic, in-memory source, not a network or ordering protocol. */
export function createLiveSource() {
  let rows = INITIAL_OBSERVATIONS.map((row) => ({ ...row }))
  let cursor = 0
  const listeners = new Set<(message: FeedMessage) => void>()
  return {
    get cursor() {
      return cursor
    },
    get subscriberCount() {
      return listeners.size
    },
    get rows() {
      return rows.map((row) => ({ ...row }))
    },
    subscribe(listener: (message: FeedMessage) => void) {
      listeners.add(listener)
      // Registration and snapshot are synchronous in this fixture. A remote
      // source needs an atomic snapshot/cursor handoff to avoid losing events.
      listener({ kind: "snapshot", rows: rows.map((row) => ({ ...row })), cursor })
      return () => {
        listeners.delete(listener)
      }
    },
    advance() {
      const event = LIVE_EVENTS[cursor]
      if (!event) return false
      const byId = new Map(rows.map((row) => [row.id, row]))
      byId.set(event.row.id, { ...event.row })
      const ordered = [...byId.values()].sort((a, b) => a.minute - b.minute)
      const removed = ordered.slice(0, -RETAINED_RECORDS).map((row) => row.id)
      rows = ordered.slice(-RETAINED_RECORDS)
      cursor += 1
      for (const listener of listeners) {
        listener({ kind: "change", row: { ...event.row }, removed, cursor })
      }
      return true
    },
  }
}

export type LiveSource = ReturnType<typeof createLiveSource>
type LiveChartHandle = ComponentRef<typeof LineChart>

/** Connect only after React mounts the chart and supplies its ref. */
export function connectLiveChart(
  source: LiveSource,
  chart: LiveChartHandle,
  onReadback: (rows: Observation[], cursor: number) => void,
) {
  const retainedIds = new Set<string>()
  return source.subscribe((message) => {
    if (message.kind === "snapshot") {
      chart.clear()
      chart.pushMany(message.rows)
      retainedIds.clear()
      for (const row of message.rows) retainedIds.add(row.id)
    } else {
      for (const id of message.removed) {
        chart.remove(id)
        retainedIds.delete(id)
      }
      if (retainedIds.has(message.row.id)) {
        chart.update(message.row.id, (previous) => ({ ...previous, ...message.row }))
      } else if (!message.removed.includes(message.row.id)) {
        chart.push(message.row)
        retainedIds.add(message.row.id)
      }
    }
    // Inspect the chart's retained store, rather than echoing the source rows.
    const actual = chart.getData().map((row) => ({
      id: String(row.id),
      minute: Number(row.minute),
      value: Number(row.value),
    }))
    onReadback(actual, message.cursor)
  })
}

.task-live {
  min-width: 0;
}
.task-live__controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}
.task-live__controls button {
  min-height: 40px;
  padding: 0.4rem 0.8rem;
}
.task-live__table {
  overflow-x: auto;
  margin: 1rem 0;
}
.task-live__table table {
  width: 100%;
  border-collapse: collapse;
}
.task-live__table caption {
  text-align: left;
  font-weight: 600;
  margin-bottom: 0.5rem;
}
.task-live__table th,
.task-live__table td {
  text-align: left;
  padding: 0.5rem;
  border-bottom: 1px solid var(--border-color, #aaa);
}
